    x = (17 * x + 43) % 256

val = (x * 14 - 50) // 3

# Unique prime factors of val
factors = set()
d = 2
temp = val
while d * d <= temp:
    if temp % d == 0:
        factors.add(d)
        while temp % d == 0:
            temp //= d
    d += 1
if temp > 1:
    factors.add(temp)

prod = 1
for f in factors:
    prod *= f

final_answer = prod

teams = 8
total_matches = (teams * (teams - 1) // 2) * 2 # 56

total_points = 0
for m in range(total_matches):
